    public class ExecutionEngineTests
    {
        [Fact]
        public void Evaluate_ShouldReturnFalse_WhenNodeIsEmpty()
        {
            // Arrange
            var engine = new ExecutionEngine();
            var node = new RuleNode(LogicalOperator.And);

            // Act
            var result = engine.Evaluate("Sujet de test", "expediteur@test.com", node);

            // Assert
            Assert.False(result);
        }

        [Fact]
        public void Evaluate_ShouldReturnTrue_WhenSenderMatchesEqualsCriterion()
        {
            // Arrange
            var engine = new ExecutionEngine();
            var node = new RuleNode(LogicalOperator.And);
            node.AddCriterion(new RuleCriterion(MailField.Sender, MatchOperator.Equals, "boss@company.com"));

            // Act
            var result = engine.Evaluate("Sujet", "boss@company.com", node);

            // Assert
            Assert.True(result);
        }

        [Fact]
        public void Evaluate_ShouldReturnFalse_WhenSenderDoesNotMatchEqualsCriterion()
        {
            // Arrange
            var engine = new ExecutionEngine();
            var node = new RuleNode(LogicalOperator.And);
            node.AddCriterion(new RuleCriterion(MailField.Sender, MatchOperator.Equals, "boss@company.com"));

            // Act
            var result = engine.Evaluate("Sujet", "employe@company.com", node);

            // Assert
            Assert.False(result);
        }

        [Fact]
        public void Evaluate_ShouldReturnTrue_WhenSubjectMatchesContainsCriterion()
        {
            // Arrange
            var engine = new ExecutionEngine();
            var node = new RuleNode(LogicalOperator.And);
            node.AddCriterion(new RuleCriterion(MailField.Subject, MatchOperator.Contains, "Urgent"));

            // Act
            var result = engine.Evaluate("Ceci est un message URGENT !", "expediteur@test.com", node);

            // Assert
            Assert.True(result);
        }

        [Fact]
        public void Evaluate_ShouldReturnTrue_WhenOrNodeHasOneValidCriterion()
        {
            // Arrange
            var engine = new ExecutionEngine();
            var node = new RuleNode(LogicalOperator.Or);
            node.AddCriterion(new RuleCriterion(MailField.Sender, MatchOperator.Equals, "inconnu@test.com"));
            node.AddCriterion(new RuleCriterion(MailField.Subject, MatchOperator.Contains, "Facture"));

            // Act
            var result = engine.Evaluate("Votre facture mensuelle", "compta@entreprise.com", node);

            // Assert
            Assert.True(result);
        }

        [Fact]
        public void Evaluate_ShouldReturnTrue_WhenSubjectMatchesRegexCriterion_IgnoringCase()
        {
            // Arrange
            var engine = new ExecutionEngine();
            var node = new RuleNode(LogicalOperator.And);
            node.AddCriterion(new RuleCriterion(MailField.Subject, MatchOperator.RegexMatch, @"^\[CEDA\] : Actions demandées:"));

            // Act
            var matchResult = engine.Evaluate("[ceda] : actions demandées: Lot 42", "test@cnam.fr", node);
            var noMatchResult = engine.Evaluate("RE: [CEDA] : Actions demandées:", "test@cnam.fr", node);

            // Assert
            Assert.True(matchResult);
            Assert.False(noMatchResult);
        }

        [Fact]
        public void Evaluate_ShouldReturnTrue_WhenCategoryMatchesExactNode_OrNodeAndChildren()
        {
            // Arrange
            var engine = new ExecutionEngine();

            var exactNode = new RuleNode(LogicalOperator.And);
            exactNode.AddCriterion(new RuleCriterion(MailField.Category, MatchOperator.ExactNode, "Administratif-Syndicats"));

            var hierarchyNode = new RuleNode(LogicalOperator.And);
            hierarchyNode.AddCriterion(new RuleCriterion(MailField.Category, MatchOperator.NodeAndChildren, "Administratif"));

            var appliedCategories = new[] { "Administratif-Syndicats", "Autre" };

            // Act & Assert
            Assert.True(engine.Evaluate("Sujet", "exp@cnam.fr", appliedCategories, exactNode));
            Assert.False(engine.Evaluate("Sujet", "exp@cnam.fr", new[] { "Administratif" }, exactNode));
            Assert.True(engine.Evaluate("Sujet", "exp@cnam.fr", appliedCategories, hierarchyNode));
        }
    }
